style.css:
@-moz-document domain("youtube.com") {
/* Ana video ızgarası düzeni */
  ytd-rich-grid-renderer {
    --ytd-rich-grid-items-per-row: 5 !important;
    --ytd-rich-grid-posts-per-row: 5 !important;
    --ytd-thumbnail-width: 160px !important;
  }
  
  /* İçerik görüntüleme ayarı */
  ytd-rich-grid-row #contents.ytd-rich-grid-row {
    display: contents !important;
  }
  
  /* Öğe genişliği */
  ytd-rich-item-renderer {
    width: calc(100%/5 - 16px) !important;
    max-width: none !important;
  }
  
  /* Küçük resim boyutu */
  ytd-thumbnail.ytd-rich-grid-media {
    width: 100% !important;
    min-width: unset !important;
  }
  
  /* Başlık yazı tipi boyutu */
  #video-title.ytd-rich-grid-media {
    font-size: 14px !important;
    line-height: 1.4 !important;
  }
  
  /* Shorts için düzeltmeler */
  ytd-reel-item-renderer {
    width: 140px !important;
    max-width: 140px !important;
    margin: 0 4px !important;
  }
}
